"""Render saved aggregate QC504 diagnostics; no strategy execution or data export."""
from pathlib import Path
import csv,hashlib,json,math
ROOT=Path(__file__).resolve().parents[1]; RAW=ROOT/'.local/qc504-v1';OUT=ROOT/'.local/performance/qc504-v1'
CASES=['recent','long','cost25']
NAMES={'recent':'2020–2025 · source defaults','long':'2010–2025 · source defaults','cost25':'2020–2025 · 25bp slippage'}

def build():
    runs=[];annual=[];assets={};selections={}
    ledger=json.loads((RAW/'attempts.json').read_text())
    for case in CASES:
        rows=[json.loads(x) for x in json.loads((RAW/f'{case}-summary-cells.json').read_text())]
        full=[r for r in rows if r.get('kind')=='overall']
        if len(full)!=1:
            if case!='long':raise ValueError('Missing complete summary: '+case)
            a=ledger['attempts'][-1]
            runs.append(dict(case=case,cagr=a['native_cagr_pct']/100,dd=-a['native_dd_pct']/100,end=a['native_end_usd'],sharpe=None,calmar=None,longest_uw=None,rejects='at least one observed in prior identical long run',other_fills='unavailable',fees=5286015.90,max_gross=None,min_cash=None,comparison_status='NATIVE ONLY: annual/custom temporal/attribution summaries unavailable; vendor-defined CAGR/DD; native Sharpe 1.772 shown separately, not comparable to custom Sharpe'))
            assets[case]=dict(values=[],residual_usd=None);selections[case]=dict(top_target_days='Unavailable: custom log retrieval failed')
            continue
        full=full[0];ys=sorted([r for r in rows if r.get('kind')=='annual'],key=lambda r:r['year'])
        expected=16 if case=='long' else 6
        if len(ys)!=expected or any(r.get('case')!=case for r in rows):raise ValueError('Missing/wrong years/case')
        nav=10000.;moment=0.;squares=0.;n=0;uw=0
        for r in ys:
            nav*=1+r['ret'];moment+=r.get('return_sum',0.);squares+=r.get('return_square_sum',0.);n+=r['n'];uw+=r['global_uw']
            if abs(nav-r['end'])>max(.1,abs(nav)*1e-8):raise ValueError('Annual NAV mismatch')
        if abs(nav-full['end'])>max(.1,abs(nav)*1e-8) or n!=full['n'] or uw!=full['uw']:raise ValueError('Full totals mismatch')
        sd=math.sqrt(max(0,(squares-moment*moment/n)/(n-1)))
        if all('return_sum' in r for r in ys) and sd>1e-15 and abs(moment/n/sd*math.sqrt(252)-full['sharpe'])>1e-5:raise ValueError('Sharpe moment mismatch')
        if abs(full['calmar']-full['cagr']/abs(full['dd']))>1e-9:raise ValueError('Calmar mismatch')
        full['comparison_status']='conditional: rejected orders' if full['rejects'] else 'completed; native accounting audit limited'
        runs.append(full);annual.extend(ys)
        assets[case]=next(r for r in rows if r.get('kind')=='assets')
        selections[case]=next(r for r in rows if r.get('kind')=='selections')
    if runs[0]['calendar_hash']!=runs[2]['calendar_hash']:raise ValueError('Recent/cost calendars mismatch')
    receipt={'study_id':'qc504-evaluation-v1','status':'completed-with-missing-long-custom-evidence','git_sha':ledger['git_sha'],
      'source_sha256':ledger['source_sha256'],'attempts':ledger['attempts'],
      'engine_observed':'LEAN2.5.0.0.18209; differs from prior sector run18205',
      'checks':['annual/full NAV compounding','recent/cost Sharpe from annual daily return moments; long custom summaries unavailable','Calmar formula','recent/cost global underwater totals','recent/cost calendar hash'],
      'limits':['own hosted rerun, not independent engine/data implementation','different window and10k capital from normalized leaderboard','rejected orders affect realized paths; no silent repairs','sleeve counts are intended target days, not sleeve P&L','fund market-value exposure omits embedded leverage','no market impact/capacity validation or financing qualification','historical development sample; not clean OOS'],
      'hashes':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in [RAW/'published-main.py']+[RAW/f'{c}-source.py' for c in CASES]+[RAW/f'{c}-summary-cells.json' for c in CASES]}}
    data={'names':NAMES,'runs':runs,'annual':annual,'assets':assets,'selections':selections,'evidence':receipt}
    OUT.mkdir(parents=True,exist_ok=True);(OUT/'comparison.json').write_text(json.dumps(data,indent=2)+'\n')
    with (OUT/'annual.csv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=['case','year','n','ret','dd','sharpe','annual_calmar','uw','global_uw','longest_uw','end'],extrasaction='ignore');w.writeheader();w.writerows(annual)
    (OUT/'index.html').write_text(PAGE.replace('PAYLOAD',json.dumps(data).replace('</','<\\/')))
    (OUT/'manifest.json').write_text(json.dumps({p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in OUT.iterdir() if p.is_file() and p.name!='manifest.json'},indent=2)+'\n')
    (ROOT/'docs/tasks/evidence/2026-10-26-qc504-evaluation.json').write_text(json.dumps(receipt,indent=2)+'\n')
    print(json.dumps({'runs':runs,'assets':assets,'annual_rows':len(annual)},indent=2))

PAGE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>504 · copied-strategy evaluation</title><style>body{font:15px system-ui;background:#f4f6f8;color:#203444;margin:0}main{max-width:1260px;margin:auto;padding:28px}p{line-height:1.6}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{background:white;padding:20px;border:1px solid #cdd9e0;border-top:5px solid #398074;border-radius:8px}.card h2{font-size:19px;margin:0 0 12px}.big{font-size:28px;font-weight:700}.warn{background:#fff0d3;border-left:4px solid #a67115;padding:15px}table{border-collapse:collapse;width:100%;background:white;font-variant-numeric:tabular-nums}td,th{padding:9px;text-align:right;border-bottom:1px solid #d8e1e7;white-space:nowrap}td:first-child,th:first-child{text-align:left}th{background:#e4ecf2}.scroll{overflow:auto}select{padding:8px;font:inherit}.small{font-size:12px;color:#526a7b}a{color:#135c8b}@media(max-width:850px){.cards{grid-template-columns:1fr}}</style><main><p class="small">26 October 2026 · Quant trading lab · frozen copied-source evaluation</p><h1>What survives our own rerun of #504?</h1><p>Official private clone · unchanged four trading rules · $10,000 starting capital · fixed historical windows · summary metrics calculated inside QuantConnect.</p><p class="warn">These are our hosted diagnostics, not an independent engine/data replication or an exact rolling-five-year leaderboard reproduction. Check rejected orders before interpreting returns. No market-impact or capacity validation; ETF market-value exposure omits embedded leverage.</p><div class="cards" id="cards"></div><h2>Year-by-year return</h2><p>The long case includes earlier crises, but its custom annual summaries could not be retrieved. Long-column blanks mean missing evidence; recent/cost blanks before 2020 are outside their windows.</p><div class="scroll"><table id="matrix"></table></div><h2>All annual diagnostics</h2><div class="scroll"><table id="annual"></table></div><h2>What generated gains and losses?</h2><label>Run <select id="case"><option value="recent">2020–2025 source defaults</option><option value="long">2010–2025 source defaults</option><option value="cost25">2020–2025 25bp slippage</option></select></label><p>Native per-asset realized P&amp;L plus marked holdings, after incurred fees and without hypothetical exit fees. This aggregates the engine's books; it is not independent accounting or a causal estimate of a sleeve's contribution.</p><p id="residual"></p><div class="scroll"><table id="assets"></table></div><h2>Sleeve selection diagnostics</h2><p>Counts show days each sleeve intended to target an asset. Shared holdings and actual execution prevent assigning realized P&amp;L to sleeves from these counts alone.</p><pre id="selections"></pre><h2>Ideas to carry forward</h2><ul><li>Test combining distinct signal families against their individual controls.</li><li>Track overlapping holdings: four sleeves can still converge on the same leveraged or volatility product.</li><li>Separate a target rule's performance from rejected-order effects and opening-gap exposure.</li><li>Compare drawdown depth, recovery time and cost sensitivity across the same dates before tuning.</li></ul><p>Recent/cost Sharpe uses daily account returns, zero risk-free rate and sqrt252. Full Calmar uses calendar-time CAGR; annual Calmar uses that year's return and reset drawdown. Underwater measures carry historical peaks in the overall view; annual longest runs reset at year-end. All inspected history is development evidence.</p><p><a href="annual.csv">Annual CSV</a> · <a href="comparison.json">Evidence and metrics</a> · <a href="https://www.quantconnect.com/project/38484741">Our private clone</a> · <a href="https://www.quantconnect.com/strategies/504/">Original and attribution</a></p></main><script>const d=PAYLOAD,cs=['recent','long','cost25'],pct=v=>v==null?'—':(v*100).toFixed(2)+'%',num=v=>v==null?'—':v.toFixed(2),usd=v=>v==null?'unavailable':'$'+Math.round(v).toLocaleString();document.getElementById('cards').innerHTML=d.runs.map(r=>`<article class="card"><h2>${d.names[r.case]}</h2><div class="big">${pct(r.cagr)} CAGR</div><p>${pct(r.dd)} max drawdown<br>${num(r.sharpe)} Sharpe · ${num(r.calmar)} Calmar<br><b>${r.longest_uw??'unavailable'} sessions</b> longest underwater<br>${usd(r.end)} ending NAV<br>${r.rejects} rejected orders · ${r.other_fills} non-MOO fills<br>${usd(r.fees)} native fees<br>${num(r.max_gross)}× maximum ETF market-value exposure<br>${usd(r.min_cash)} minimum cash</p><p class="small">${r.comparison_status}</p></article>`).join('');const ys=Array.from({length:16},(_,i)=>String(2010+i));const get=(c,y)=>d.annual.find(r=>r.case===c&&r.year===y);document.getElementById('matrix').innerHTML='<tr><th>Year</th>'+cs.map(c=>`<th>${d.names[c]}</th>`).join('')+'</tr>'+ys.map(y=>'<tr><td>'+y+'</td>'+cs.map(c=>`<td>${pct(get(c,y)?.ret)}</td>`).join('')+'</tr>').join('');document.getElementById('annual').innerHTML='<tr><th>Run / year</th><th>Return</th><th>Max DD</th><th>Sharpe</th><th>Calmar</th><th>Carried-peak UW</th><th>Longest UW sessions</th></tr>'+d.annual.map(r=>`<tr><td>${r.case} · ${r.year}</td><td>${pct(r.ret)}</td><td>${pct(r.dd)}</td><td>${num(r.sharpe)}</td><td>${num(r.annual_calmar)}</td><td>${pct(r.global_uw/r.n)}</td><td>${r.longest_uw}</td></tr>`).join('');function show(){let c=document.getElementById('case').value;document.getElementById('assets').innerHTML='<tr><th>Asset</th><th>Native P&amp;L USD</th><th>Incurred fees USD</th></tr>'+d.assets[c].values.map(a=>`<tr><td>${a[0]}</td><td>${usd(a[1])}</td><td>${usd(a[2])}</td></tr>`).join('');document.getElementById('residual').textContent='Asset P&L to account-gain residual: $'+(d.assets[c].residual_usd==null?'unavailable':d.assets[c].residual_usd.toFixed(4))+'. Any material residual remains unexplained.';document.getElementById('selections').textContent=JSON.stringify(d.selections[c].top_target_days,null,2)}document.getElementById('case').onchange=show;show();</script></html>'''
if __name__=='__main__':build()
